issue.body:
Reduced test case:
```
#include <stdio.h>
#include <stdint.h>
int16_t g;
int32_t f;
uint32_t h;
uint64_t j = 6;
static uint64_t o(int16_t x, uint32_t *a, int16_t ac) {
  if (!x) j |= f;
  f = ac ? 7 % ac : 7;
  return j;
}
int main() {
  uint64_t v1 =  o(g, &h, 8);
  uint64_t v2 = o(v1, &h, 0);
  o(v2 >> 8, &h, 0);
  printf("%lu\n", j);
  return 0;
}
```

```
$ gcc -O0 -fsanitize=address,undefined test.c && ./a.out
7
$ bin/clang -O3 --target=riscv64-linux-gnu test.c
$ qemu-riscv64 -L /usr/riscv64-linux-gnu ./a.out
13
```

llvm version: ba6b2d22af177a72b132cdb8e9350a708f282d2c
qemu version: v8.2.0

patch:
commit 3197f9d8b0efc3efdc531421bd11c16305d9b1ff
Author: Yingwei Zheng <dtcxzyw2333@gmail.com>
Date:   Thu Apr 11 12:48:52 2024 +0800

    [InstSimplify] Make sure the simplified value doesn't generate poison in threadBinOpOverSelect (#87075)

    Alive2: https://alive2.llvm.org/ce/z/y_Jmdn
    Fix https://github.com/llvm/llvm-project/issues/87042.

diff --git a/llvm/lib/Analysis/InstructionSimplify.cpp b/llvm/lib/Analysis/InstructionSimplify.cpp
index 9ff3faff7990..3c943a09a9c2 100644
--- a/llvm/lib/Analysis/InstructionSimplify.cpp
+++ b/llvm/lib/Analysis/InstructionSimplify.cpp
@@ -440,7 +440,8 @@ static Value *threadBinOpOverSelect(Instruction::BinaryOps Opcode, Value *LHS,
     // Check that the simplified value has the form "X op Y" where "op" is the
     // same as the original operation.
     Instruction *Simplified = dyn_cast<Instruction>(FV ? FV : TV);
-    if (Simplified && Simplified->getOpcode() == unsigned(Opcode)) {
+    if (Simplified && Simplified->getOpcode() == unsigned(Opcode) &&
+        !Simplified->hasPoisonGeneratingFlags()) {
       // The value that didn't simplify is "UnsimplifiedLHS op UnsimplifiedRHS".
       // We already know that "op" is the same as for the simplified value.  See
       // if the operands match too.  If so, return the simplified value.

tests.test_body:
define i64 @test(i1 %cond, i64 %x) {
  %or1 = or disjoint i64 %x, 7
  %sel1 = select i1 %cond, i64 %or1, i64 %x
  %or2 = or i64 %sel1, 7
  ret i64 %or2
}
